import{_ as a,o as t,c as i,a5 as n}from"./chunks/framework.DbSlGjul.js";const u=JSON.parse('{"title":"Troubleshooting","description":"","frontmatter":{},"headers":[],"relativePath":"reference/troubleshooting.md","filePath":"reference/troubleshooting.md","lastUpdated":1788882780000}'),o={name:"reference/troubleshooting.md"};function s(r,e,d,l,h,c){return t(),i("div",null,[...e[0]||(e[0]=[n('<h1 id="troubleshooting" tabindex="-1">Troubleshooting <a class="header-anchor" href="#troubleshooting" aria-label="Permalink to &quot;Troubleshooting&quot;">​</a></h1><h2 id="an-attachment-does-not-fit" tabindex="-1">An attachment does not fit <a class="header-anchor" href="#an-attachment-does-not-fit" aria-label="Permalink to &quot;An attachment does not fit&quot;">​</a></h2><p>Print one cell and one attachment base using the same material and profile. Check for elephant&#39;s foot, warping, or excess material before modifying the CAD. If sanding is required, apply it consistently and record it.</p><h2 id="a-threaded-component-binds" tabindex="-1">A threaded component binds <a class="header-anchor" href="#a-threaded-component-binds" aria-label="Permalink to &quot;A threaded component binds&quot;">​</a></h2><p>Remove stringing and debris, then test the matching calibration piece. Keep the part aligned with the thread axis and do not force initial engagement. Record sanding or lubrication because either can change task resistance.</p><h2 id="a-module-moves-during-a-trial" tabindex="-1">A module moves during a trial <a class="header-anchor" href="#a-module-moves-during-a-trial" aria-label="Permalink to &quot;A module moves during a trial&quot;">​</a></h2><p>Stop if continuation is unsafe. Preserve the trial result, describe the displacement in <code>notes</code>, and reseat the module before continuing. For repeated release, verify cell tolerances and mounting orientation.</p><h2 id="a-printed-part-breaks" tabindex="-1">A printed part breaks <a class="header-anchor" href="#a-printed-part-breaks" aria-label="Permalink to &quot;A printed part breaks&quot;">​</a></h2><p>Record the trial as it occurred. Photograph the damage when useful, replace the component with the same print profile, and note the replacement. Do not substitute an unreported rerun.</p><h2 id="completion-time-appears-as-a-date" tabindex="-1">Completion time appears as a date <a class="header-anchor" href="#completion-time-appears-as-a-date" aria-label="Permalink to &quot;Completion time appears as a date&quot;">​</a></h2><p>Format the spreadsheet column as a plain number and enter decimal seconds without units. Use <code>12.9</code>, not <code>12.9 s</code> or a clock value.</p><h2 id="failed-trials-have-no-time" tabindex="-1">Failed trials have no time <a class="header-anchor" href="#failed-trials-have-no-time" aria-label="Permalink to &quot;Failed trials have no time&quot;">​</a></h2><p>This is expected. <code>completion_time_s</code> is only populated for successful trials. Use <code>outcome=timeout</code> for a trial that reaches the time limit.</p><h2 id="simulation-geometry-loads-at-the-wrong-scale" tabindex="-1">Simulation geometry loads at the wrong scale <a class="header-anchor" href="#simulation-geometry-loads-at-the-wrong-scale" aria-label="Permalink to &quot;Simulation geometry loads at the wrong scale&quot;">​</a></h2><p>Verify the asset units and the loader&#39;s unit conversion. Check both visual and collision geometry before changing the global scene scale.</p><h2 id="a-simulation-joint-moves-in-the-wrong-direction" tabindex="-1">A simulation joint moves in the wrong direction <a class="header-anchor" href="#a-simulation-joint-moves-in-the-wrong-direction" aria-label="Permalink to &quot;A simulation joint moves in the wrong direction&quot;">​</a></h2><p>Inspect the joint axis, parent-child order, and initial pose. Compare the full motion with the physical mechanism, not only the rendered rest configuration.</p><h2 id="simulation-contact-is-unstable" tabindex="-1">Simulation contact is unstable <a class="header-anchor" href="#simulation-contact-is-unstable" aria-label="Permalink to &quot;Simulation contact is unstable&quot;">​</a></h2><p>Begin with one environment and a conservative timestep. Inspect collision geometry, penetration at reset, solver settings, drive gains, and mass ratios. Treat the supplied physical properties as nominal rather than identified values.</p><h2 id="an-isaac-lab-asset-cannot-be-found" tabindex="-1">An Isaac Lab asset cannot be found <a class="header-anchor" href="#an-isaac-lab-asset-cannot-be-found" aria-label="Permalink to &quot;An Isaac Lab asset cannot be found&quot;">​</a></h2><p>The simulation repository uses Git submodules. From the repository root, initialize or update them with:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> submodule</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> update</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --init</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --recursive</span></span></code></pre></div><p>The <code>dependencies/HiveBoard</code>, <code>dependencies/curobo</code>, and <code>dependencies/duatic_dynaarm</code> directories should then contain their respective repositories.</p><h2 id="an-isaac-lab-task-is-not-registered" tabindex="-1">An Isaac Lab task is not registered <a class="header-anchor" href="#an-isaac-lab-task-is-not-registered" aria-label="Permalink to &quot;An Isaac Lab task is not registered&quot;">​</a></h2><p>Run the environment-listing script inside the project environment:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">uv</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> python</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/list_envs.py</span></span></code></pre></div><p>Use the exact <code>Isaac-HiveBoard-*</code> identifier printed by the script. If imports fail, run <code>uv sync</code> from the repository root and continue using <code>uv run</code> for subsequent commands.</p>',27)])])}const m=a(o,[["render",s]]);export{u as __pageData,m as default};
